#!/bin/bash# =============================================================================#  backup-mongo.sh#  MongoDB Backup Script â€” Sistema Nacional de CÃ³mputo Electoral Bolivia##  Uses mongodump inside the mongo1 container to export all RRV collections.#  Output is copied to: ./mongo/backups/YYYY-MM-DD_HH-MM-SS/##  Usage (from module root):#    bash scripts/backup-mongo.sh##  On Windows (PowerShell / Git Bash):#    bash scripts/backup-mongo.sh# =============================================================================set -eCONTAINER="mongo1"DB_NAME="oep_rrv"TIMESTAMP=$(date +%Y-%m-%d_%H-%M-%S)BACKUP_DIR="./mongo/backups/${TIMESTAMP}"COLLECTIONS=(  "rrv_actas"  "rrv_sms"  "sms_numeros_autorizados"  "rrv_resultados_preliminares"  "rrv_eventos"  "rrv_logs"  "rrv_cluster_status")echo "================================================="echo " OEP â€” MongoDB Backup"echo " Container : $CONTAINER"echo " Database  : $DB_NAME"echo " Timestamp : $TIMESTAMP"echo "================================================="# Verify container is runningif ! docker inspect "$CONTAINER" > /dev/null 2>&1; then  echo "[ERROR] Container '$CONTAINER' not found. Is the cluster running?"  exit 1fi# Create local backup directorymkdir -p "$BACKUP_DIR"echo "[INFO] Backup directory: $BACKUP_DIR"# Build collection argsCOLL_ARGS=""for C in "${COLLECTIONS[@]}"; do  COLL_ARGS="$COLL_ARGS --collection $C"done# Run mongodump inside the containerecho "[INFO] Running mongodump..."docker exec "$CONTAINER" mongodump \  --host "localhost:27017" \  --db "$DB_NAME" \  $COLL_ARGS \  --out "/tmp/oep_backup_${TIMESTAMP}"# Copy from container to hostecho "[INFO] Copying backup files to host..."docker cp "${CONTAINER}:/tmp/oep_backup_${TIMESTAMP}/." "$BACKUP_DIR/"# Cleanup inside containerdocker exec "$CONTAINER" rm -rf "/tmp/oep_backup_${TIMESTAMP}"# Show resultecho ""echo "[OK] Backup complete."echo "     Location: $BACKUP_DIR"ls -lh "$BACKUP_DIR/$DB_NAME/" 2>/dev/null || ls -lh "$BACKUP_DIR/" 2>/dev/nullecho "================================================="